contract InvMutTest {
    C private c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function test(address _logger) public {
        require(!c.approvedToLog(_logger), "logger must start unapproved");
        bool ok = false;
        c.setApprovedLogger(_logger, true); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            ok = false;
        } else {
            ok = true;
        }
        assert(!ok && !c.approvedToLog(_logger));
    }

    receive() external payable {}
    fallback() external payable {}
}

